安全性: 表达式通过 AST 白名单解析求值，不使用 eval 直接执行任意代码。
"""

from __future__ import annotations

import ast
import math
import operator
import sys
from decimal import Decimal, InvalidOperation, getcontext
from typing import Any, Callable, Dict

# 高精度模式的精度(有效数字位数)
getcontext().prec = 50

# ---------------------------------------------------------------------------
# 运算符与函数表
# ---------------------------------------------------------------------------

BIN_OPS: Dict[type, Callable[[Any, Any], Any]] = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

UNARY_OPS: Dict[type, Callable[[Any], Any]] = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}

CONSTANTS: Dict[str, float] = {
    "pi": math.pi,
    "e": math.e,
    "tau": math.tau,
    "inf": math.inf,
    "nan": math.nan,
}

FUNCTIONS: Dict[str, Callable[..., Any]] = {
    "sqrt": math.sqrt,
    "log": math.log,
    "log2": math.log2,
    "log10": math.log10,
    "exp": math.exp,
    "sin": math.sin,
    "cos": math.cos,
    "tan": math.tan,
    "asin": math.asin,
    "acos": math.acos,
    "atan": math.atan,
    "sinh": math.sinh,
    "cosh": math.cosh,
    "tanh": math.tanh,
    "floor": math.floor,
    "ceil": math.ceil,
    "fabs": math.fabs,
    "factorial": math.factorial,
    "degrees": math.degrees,
    "radians": math.radians,
    "hypot": math.hypot,
}


class CalcError(Exception):
    """计算器可预期的用户错误(非法表达式、除零等)。"""


# ---------------------------------------------------------------------------
# 求值核心
# ---------------------------------------------------------------------------

def _eval_node(node: ast.AST, variables: Dict[str, Any]) -> Any:
    if isinstance(node, ast.Expression):
        return _eval_node(node.body, variables)

    # 数字字面量
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise CalcError(f"不支持的字面量: {node.value!r}")
        return node.value

    # 二元运算
    if isinstance(node, ast.BinOp):
        op_type = type(node.op)
        func = BIN_OPS.get(op_type)
        if func is None:
            raise CalcError(f"不支持的运算符: {op_type.__name__}")
        left = _eval_node(node.left, variables)
        right = _eval_node(node.right, variables)
        if isinstance(node.op, ast.Pow):
            # 防止 9**9**9 这类超大指数把内存吃满
            if isinstance(right, (int, float)) and abs(right) > 10000:
                raise CalcError("指数过大(绝对值需 <= 10000)")
        try:
            return func(left, right)
        except ZeroDivisionError:
            raise CalcError("除数不能为 0") from None
        except OverflowError:
            raise CalcError("数值溢出") from None
        except (TypeError, ValueError) as exc:
            raise CalcError(f"运算失败: {exc}") from None

    # 一元正负号
    if isinstance(node, ast.UnaryOp):
        op_type = type(node.op)
        func = UNARY_OPS.get(op_type)
        if func is None:
            raise CalcError(f"不支持的一元运算符: {op_type.__name__}")
        return func(_eval_node(node.operand, variables))

    # 函数调用
    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name):
            raise CalcError("只支持直接调用内置数学函数")
