        if node.keywords:
            raise CalcError("函数不支持关键字参数")
        try:
            return func(*args)
        except ZeroDivisionError:
            raise CalcError("除数不能为 0") from None
        except (ValueError, TypeError, OverflowError) as exc:
            raise CalcError(f"{name}() 参数错误: {exc}") from None

    # 变量 / 常量
    if isinstance(node, ast.Name):
        if node.id in variables:
            return variables[node.id]
        if node.id in CONSTANTS:
            return CONSTANTS[node.id]
        raise CalcError(f"未知名称: {node.id}")

    raise CalcError(f"不支持的表达式成分: {type(node).__name__}")


def evaluate(expression: str, variables: Dict[str, Any] | None = None) -> Any:
    """计算一个表达式字符串并返回结果。"""
    variables = variables if variables is not None else {}
    expression = expression.strip()
    if not expression:
        raise CalcError("表达式为空")

    # 兼容部分用户习惯写法: 用 ^ 表示乘方
    expression = expression.replace("^", "**")

    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        raise CalcError(f"语法错误: {expression!r}") from None

    return _eval_node(tree, variables)


# ---------------------------------------------------------------------------
# 高精度模式 (Decimal)
# ---------------------------------------------------------------------------

def _to_decimal(value: Any) -> Decimal:
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    # 通过字符串转换，避免二进制浮点误差被带入
    return Decimal(str(value))


DECIMAL_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Mod: operator.mod,
}


def _eval_decimal_node(node: ast.AST, variables: Dict[str, Any]) -> Decimal:
    if isinstance(node, ast.Expression):
        return _eval_decimal_node(node.body, variables)

    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise CalcError(f"不支持的字面量: {node.value!r}")
        return _to_decimal(node.value)

    if isinstance(node, ast.BinOp):
        op_type = type(node.op)
        func = DECIMAL_BIN_OPS.get(op_type)
        if func is not None:
            left = _eval_decimal_node(node.left, variables)
            right = _eval_decimal_node(node.right, variables)
            try:
                return func(left, right)
            except ZeroDivisionError:
                raise CalcError("除数不能为 0") from None
            except InvalidOperation:
                raise CalcError("无效的十进制运算") from None
        if isinstance(node.op, ast.Pow):
            base = _eval_decimal_node(node.left, variables)
            exp = _eval_decimal_node(node.right, variables)
            if exp != exp.to_integral_value():
                raise CalcError("高精度模式下指数必须是整数")
            if abs(exp) > 10000:
                raise CalcError("指数过大(绝对值需 <= 10000)")
            return base ** int(exp)
        raise CalcError(f"高精度模式不支持的运算符: {op_type.__name__}")

    if isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return -_eval_decimal_node(node.operand, variables)
        if isinstance(node.op, ast.UAdd):
            return +_eval_decimal_node(node.operand, variables)
        raise CalcError("不支持的一元运算符")

    if isinstance(node, ast.Name):
        if node.id in variables:
            return _to_decimal(variables[node.id])
        if node.id in CONSTANTS:
            return _to_decimal(CONSTANTS[node.id])
        raise CalcError(f"高精度模式不支持名称: {node.id}")

    raise CalcError("高精度模式仅支持 + - * / % ** 和括号")


def evaluate_decimal(expression: str, variables: Dict[str, Any] | None = None) -> Decimal:
    variables = variables if variables is not None else {}
    expression = expression.strip()
    if not expression:
        raise CalcError("表达式为空")
    expression = expression.replace("^", "**")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        raise CalcError(f"语法错误: {expression!r}") from None
    return _eval_decimal_node(tree, variables)


# ---------------------------------------------------------------------------
# 输出格式化
# ---------------------------------------------------------------------------

def format_result(value: Any) -> str:
    if isinstance(value, Decimal):
        text = format(value.normalize(), "f")
        if "." in text:
            text = text.rstrip("0").rstrip(".")
        return text or "0"
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if math.isnan(value):
            return "nan"
        if math.isinf(value):
            return "inf" if value > 0 else "-inf"
        # 整数结果去掉 .0，其余保留足够精度并去掉多余的 0
        if value == int(value) and abs(value) < 1e16:
            return str(int(value))
        return f"{value:.12g}"
    return str(value)


# ---------------------------------------------------------------------------
# 命令行界面
# ---------------------------------------------------------------------------

HELP_TEXT = """可用命令:
  <表达式>      计算表达式, 例如: 1 + 2*3 、sqrt(16) 、2^10
  x = <表达式>  把结果保存为变量, 例如: rate = 0.05
  vars          列出已保存的变量
  help          显示本帮助
  quit / exit   退出

支持的运算: + - * / // % ** ( ) 以及一元正负号
支持的函数: sqrt log log2 log10 exp sin cos tan asin acos atan
            sinh cosh tanh floor ceil fabs factorial degrees radians hypot
支持的常量: pi e tau inf nan
"""


def _try_assignment(line: str, variables: Dict[str, Any], decimal_mode: bool) -> str | None:
    """若本行是赋值语句则执行并返回提示信息, 否则返回 None。"""
    if "=" not in line or line.startswith("="):
        return None
    # 排除 ==、<=、>=、!= 这类比较写法
    parts = line.split("=")
    if len(parts) != 2:
        return None
    name, expr = parts[0].strip(), parts[1].strip()
    if not name.isidentifier():
        return None
    value = evaluate_decimal(expr, variables) if decimal_mode else evaluate(expr, variables)
    variables[name] = value
    return f"{name} = {format_result(value)}"


def run_repl(decimal_mode: bool = False) -> int:
    variables: Dict[str, Any] = {}
    mode_note = "高精度模式 (Decimal, 50 位有效数字)" if decimal_mode else "浮点模式"
    print(f"简易计算器 — {mode_note}")
    print("输入 help 查看用法, quit 退出。")
    while True:
        try:
            line = input(">>> ")
        except (EOFError, KeyboardInterrupt):
            print()
            return 0

        line = line.strip()
        if not line:
            continue
        low = line.lower()
        if low in {"quit", "exit", "q"}:
            return 0
        if low in {"help", "?", "h"}:
            print(HELP_TEXT)
            continue
        if low == "vars":
            if not variables:
                print("(暂无变量)")
            else:
                for key, val in variables.items():
                    print(f"{key} = {format_result(val)}")
            continue

        try:
            message = _try_assignment(line, variables, decimal_mode)
            if message is not None:
                print(message)
                continue
            value = evaluate_decimal(line, variables) if decimal_mode else evaluate(line, variables)
            print(f"= {format_result(value)}")
        except CalcError as exc:
            print(f"错误: {exc}")
        except RecursionError:
            print("错误: 表达式嵌套过深")


def main(argv: list[str]) -> int:
    decimal_mode = False
    expressions: list[str] = []

    for arg in argv[1:]:
        if arg in {"-p", "--precise", "--decimal"}:
            decimal_mode = True
        elif arg in {"-h", "--help"}:
            print(__doc__.strip())
            return 0
        else:
            expressions.append(arg)

    if expressions:
        expression = " ".join(expressions)
        try:
            value = evaluate_decimal(expression) if decimal_mode else evaluate(expression)
            print(format_result(value))
            return 0
        except CalcError as exc:
            print(f"错误: {exc}", file=sys.stderr)
            return 1
        except RecursionError:
            print("错误: 表达式嵌套过深", file=sys.stderr)
            return 1

    # 无参数: 若有管道输入则逐行计算, 否则进入交互模式
    if not sys.stdin.isatty():
        variables: Dict[str, Any] = {}
        for raw in sys.stdin:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            try:
                message = _try_assignment(line, variables, decimal_mode)
                if message is not None:
                    print(message)
                    continue
                value = evaluate_decimal(line, variables) if decimal_mode else evaluate(line, variables)
                print(format_result(value))
            except CalcError as exc:
                print(f"错误: {exc}", file=sys.stderr)
        return 0

    return run_repl(decimal_mode)


if __name__ == "__main__":
    sys.exit(main(sys.argv))

