        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        raise CalcError("语法错误: {!r}".format(expression)) from None
    except (ValueError, MemoryError):
        raise CalcError("表达式无法解析") from None
    return _eval_decimal_node(tree, variables)


# ---------------------------------------------------------------------------
# 结果格式化
# ---------------------------------------------------------------------------

def format_result(value: Any) -> str:
    if isinstance(value, Decimal):
        text = format(value, "f")
        if "." in text:
            text = text.rstrip("0").rstrip(".")
