            return str(int(value))
        text = "{:.12g}".format(value)
        return text
    return str(value)


# ---------------------------------------------------------------------------
# 命令行界面
# ---------------------------------------------------------------------------

HELP_TEXT = """可用运算符: + - * / // % ** 以及括号 ( )
可用常量: pi e tau inf nan
可用函数: sqrt log log2 log10 exp sin cos tan asin acos atan
          sinh cosh tanh floor ceil fabs factorial degrees radians hypot
其他命令: help  显示本帮助
          vars  查看已定义变量
          quit / exit  退出
变量赋值: x = 3 + 4   （之后可直接使用 x）
高精度模式: 使用 -p 参数，例如 python calculator.py -p "0.1 + 0.2"
"""


def _split_assignment(line: str):
    """把 'name = expr' 拆成 (name, expr)；不是赋值则返回 (None, line)。"""
    try:
        tree = ast.parse(line, mode="exec")
    except SyntaxError:
