        return Decimal(str(value))
    raise CalcError("高精度模式不支持的值: {!r}".format(value))


def _eval_decimal_node(node: ast.AST, variables: Dict[str, Any]) -> Decimal:
    if isinstance(node, ast.Expression):
        return _eval_decimal_node(node.body, variables)

    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise CalcError("不支持的字面量: {!r}".format(node.value))
        return _to_decimal(node.value)

    if isinstance(node, ast.BinOp):
        op_type = type(node.op)
        func = DECIMAL_BIN_OPS.get(op_type)
        if func is not None:
            left = _eval_decimal_node(node.left, variables)
            right = _eval_decimal_node(node.right, variables)
            try:
                return func(left, right)
            except ZeroDivisionError:
                raise CalcError("除数不能为 0") from None
            except InvalidOperation:
                raise CalcError("无效的十进制运算") from None
        if isinstance(node.op, ast.Pow):
            base = _eval_decimal_node(node.left, variables)
            exp = _eval_decimal_node(node.right, variables)
            if exp != exp.to_integral_value():
                raise CalcError("高精度模式下指数必须是整数")
            if abs(exp) > MAX_EXPONENT:
                raise CalcError("指数过大（绝对值需 <= {}）".format(MAX_EXPONENT))
            try:
                return base ** int(exp)
            except (InvalidOperation, OverflowError):
                raise CalcError("数值溢出") from None
        raise CalcError("高精度模式不支持的运算符: {}".format(op_type.__name__))

    if isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.USub):
            return -_eval_decimal_node(node.operand, variables)
        if isinstance(node.op, ast.UAdd):
            return +_eval_decimal_node(node.operand, variables)
        raise CalcError("不支持的一元运算符")

    if isinstance(node, ast.Call):
        raise CalcError("高精度模式不支持函数调用，请去掉 -p 后使用")

    if isinstance(node, ast.Name):
        if node.id in variables:
            return _to_decimal(variables[node.id])
        if node.id in CONSTANTS:
            return _to_decimal(CONSTANTS[node.id])
        raise CalcError("未知名称: {}".format(node.id))

    raise CalcError("高精度模式仅支持 + - * / % ** 与括号")


def evaluate_decimal(expression: str, variables: Optional[Dict[str, Any]] = None) -> Decimal:
    """高精度求值，返回 Decimal。"""
    variables = {} if variables is None else variables
    expression = expression.strip()
    if not expression:
        raise CalcError("表达式为空")
    expression = expression.replace("^", "**")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        raise CalcError("语法错误: {!r}".format(expression)) from None
    except (ValueError, MemoryError):
        raise CalcError("表达式无法解析") from None
    return _eval_decimal_node(tree, variables)


# ---------------------------------------------------------------------------
# 结果格式化
# ---------------------------------------------------------------------------

def format_result(value: Any) -> str:
    if isinstance(value, Decimal):
        text = format(value, "f")
        if "." in text:
            text = text.rstrip("0").rstrip(".")
        return text or "0"
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if math.isnan(value):
            return "nan"
        if math.isinf(value):
            return "inf" if value > 0 else "-inf"
        if value == int(value) and abs(value) < 1e16:
            return str(int(value))
        text = "{:.12g}".format(value)
        return text
    return str(value)


# ---------------------------------------------------------------------------
# 命令行界面
# ---------------------------------------------------------------------------

HELP_TEXT = """可用运算符: + - * / // % ** 以及括号 ( )
可用常量: pi e tau inf nan
可用函数: sqrt log log2 log10 exp sin cos tan asin acos atan
          sinh cosh tanh floor ceil fabs factorial degrees radians hypot
其他命令: help  显示本帮助
          vars  查看已定义变量
          quit / exit  退出
变量赋值: x = 3 + 4   （之后可直接使用 x）
高精度模式: 使用 -p 参数，例如 python calculator.py -p "0.1 + 0.2"
"""


def _split_assignment(line: str):
    """把 'name = expr' 拆成 (name, expr)；不是赋值则返回 (None, line)。"""
    try:
        tree = ast.parse(line, mode="exec")
    except SyntaxError:
        return None, line
    if len(tree.body) != 1:
        return None, line
    stmt = tree.body[0]
    if not isinstance(stmt, ast.Assign) or len(stmt.targets) != 1:
        return None, line
    target = stmt.targets[0]
    if not isinstance(target, ast.Name):
        return None, line
    if target.id in CONSTANTS or target.id in FUNCTIONS:
        raise CalcError("不能覆盖内置常量或函数: {}".format(target.id))
    expr_src = ast.get_source_segment(line, stmt.value)
    if expr_src is None:
        return None, line
    return target.id, expr_src


def run_single(expression: str, precise: bool, variables: Dict[str, Any]):
    if precise:
        return evaluate_decimal(expression, variables)
    return evaluate(expression, variables)


def interactive(precise: bool = False) -> int:
    variables: Dict[str, Any] = {}
    mode = "高精度(Decimal)" if precise else "浮点"
    print("计算器 [{}] 已启动，输入 help 查看帮助，quit 退出。".format(mode))
    while True:
        try:
            line = input(">>> ")
        except (EOFError, KeyboardInterrupt):
            print()
            return 0
        line = line.strip()
        if not line:
            continue
        low = line.lower()
        if low in ("quit", "exit", "q"):
            return 0
        if low in ("help", "?", "h"):
            print(HELP_TEXT)
            continue
        if low in ("vars", "v"):
            if not variables:
                print("(还没有自定义变量)")
            else:
                for name, val in variables.items():
                    print("{} = {}".format(name, format_result(val)))
            continue

        try:
            name, expr = _split_assignment(line)
            if name is not None:
                value = run_single(expr, precise, variables)
                variables[name] = value
                print("{} = {}".format(name, format_result(value)))
                continue
            print(format_result(run_single(line, precise, variables)))
        except CalcError as exc:
            print("错误: {}".format(exc))
        except Exception as exc:  # 兜底，避免交互模式崩溃
            print("错误: {}".format(exc))


def main(argv: List[str]) -> int:
    args = list(argv[1:])
    precise = False
    expressions: List[str] = []

    for arg in args:
        if arg in ("-h", "--help"):
            print(HELP_TEXT)
            return 0
        if arg in ("-p", "--precise", "--decimal"):
            precise = True
        else:
            expressions.append(arg)

    # 命令行直接给出表达式
    if expressions:
        expression = " ".join(expressions)
        try:
            print(format_result(run_single(expression, precise, {})))
            return 0
        except CalcError as exc:
            print("错误: {}".format(exc), file=sys.stderr)
            return 1

    # 有标准输入且不是终端 -> 逐行计算
    if not sys.stdin.isatty():
        status = 0
        for raw in sys.stdin:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            try:
                print(format_result(run_single(line, precise, {})))
            except CalcError as exc:
                print("错误: {}".format(exc), file=sys.stderr)
                status = 1
        return status

    # 否则进入交互模式
    return interactive(precise)


if __name__ == "__main__":
    sys.exit(main(sys.argv))

