        try:
            return func(*args)
        except ZeroDivisionError:
            raise CalcError("除数不能为 0") from None
        except OverflowError:
            raise CalcError("数值溢出") from None
        except (ValueError, TypeError) as exc:
            raise CalcError("{}() 参数错误: {}".format(name, exc)) from None

    # 变量 / 常量
    if isinstance(node, ast.Name):
        if node.id in variables:
            return variables[node.id]
        if node.id in CONSTANTS:
            return CONSTANTS[node.id]
        raise CalcError("未知名称: {}".format(node.id))

    raise CalcError("不支持的表达式成分: {}".format(type(node).__name__))


def evaluate(expression: str, variables: Optional[Dict[str, Any]] = None) -> Any:
    """计算表达式字符串，返回结果（int / float）。"""
    variables = {} if variables is None else variables
    expression = expression.strip()
    if not expression:
