# ---------------------------------------------------------------------------
# 命令行界面
# ---------------------------------------------------------------------------

HELP_TEXT = """可用运算符: + - * / // % ** 以及括号 ( )
可用常量: pi e tau inf nan
可用函数: sqrt log log2 log10 exp sin cos tan asin acos atan
          sinh cosh tanh floor ceil fabs factorial degrees radians hypot
