"""


def _split_assignment(line: str):
    """把 'name = expr' 拆成 (name, expr)；不是赋值则返回 (None, line)。"""
    try:
        tree = ast.parse(line, mode="exec")
    except SyntaxError:
        return None, line
    if len(tree.body) != 1:
        return None, line
    stmt = tree.body[0]
    if not isinstance(stmt, ast.Assign) or len(stmt.targets) != 1:
        return None, line
    target = stmt.targets[0]
    if not isinstance(target, ast.Name):
        return None, line
    if target.id in CONSTANTS or target.id in FUNCTIONS:
        raise CalcError("不能覆盖内置常量或函数: {}".format(target.id))
    expr_src = ast.get_source_segment(line, stmt.value)
    if expr_src is None:
        return None, line
    return target.id, expr_src


def run_single(expression: str, precise: bool, variables: Dict[str, Any]):
    if precise:
        return evaluate_decimal(expression, variables)
    return evaluate(expression, variables)


def interactive(precise: bool = False) -> int:
    variables: Dict[str, Any] = {}
    mode = "高精度(Decimal)" if precise else "浮点"
    print("计算器 [{}] 已启动，输入 help 查看帮助，quit 退出。".format(mode))
    while True:
        try:
            line = input(">>> ")
        except (EOFError, KeyboardInterrupt):
            print()
            return 0
        line = line.strip()
        if not line:
            continue
        low = line.lower()
        if low in ("quit", "exit", "q"):
            return 0
        if low in ("help", "?", "h"):
            print(HELP_TEXT)
            continue
        if low in ("vars", "v"):
            if not variables:
                print("(还没有自定义变量)")
            else:
                for name, val in variables.items():
                    print("{} = {}".format(name, format_result(val)))
            continue

        try:
            name, expr = _split_assignment(line)
            if name is not None:
                value = run_single(expr, precise, variables)
                variables[name] = value
                print("{} = {}".format(name, format_result(value)))
                continue
            print(format_result(run_single(line, precise, variables)))
        except CalcError as exc:
            print("错误: {}".format(exc))
        except Exception as exc:  # 兜底，避免交互模式崩溃
            print("错误: {}".format(exc))


def main(argv: List[str]) -> int:
    args = list(argv[1:])
    precise = False
    expressions: List[str] = []

    for arg in args:
        if arg in ("-h", "--help"):
            print(HELP_TEXT)
            return 0
        if arg in ("-p", "--precise", "--decimal"):
            precise = True
        else:
            expressions.append(arg)

    # 命令行直接给出表达式
    if expressions:
        expression = " ".join(expressions)
        try:
            print(format_result(run_single(expression, precise, {})))
            return 0
        except CalcError as exc:
            print("错误: {}".format(exc), file=sys.stderr)
            return 1

    # 有标准输入且不是终端 -> 逐行计算
    if not sys.stdin.isatty():
        status = 0
        for raw in sys.stdin:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            try:
                print(format_result(run_single(line, precise, {})))
            except CalcError as exc:
                print("错误: {}".format(exc), file=sys.stderr)
                status = 1
        return status

    # 否则进入交互模式
    return interactive(precise)


if __name__ == "__main__":
    sys.exit(main(sys.argv))

