from __future__ import annotations

import ast
import math
import operator
import sys
from decimal import Decimal, InvalidOperation, getcontext
from typing import Any, Callable, Dict, List, Optional

# 高精度模式的精度（有效数字位数）
getcontext().prec = 50

# ---------------------------------------------------------------------------
# 运算符、常量、函数表
# ---------------------------------------------------------------------------

