    "degrees": math.degrees,
    "radians": math.radians,
    "hypot": math.hypot,
}

MAX_EXPONENT = 10000  # 幂运算指数的绝对值上限，避免 9**9**9 耗尽内存


class CalcError(Exception):
    """计算器可预期的用户错误（非法表达式、除零等）。"""


# ---------------------------------------------------------------------------
# 普通浮点模式：AST 白名单求值
# ---------------------------------------------------------------------------

def _eval_node(node: ast.AST, variables: Dict[str, Any]) -> Any:
    if isinstance(node, ast.Expression):
        return _eval_node(node.body, variables)

    # 数字字面量
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise CalcError("不支持的字面量: {!r}".format(node.value))
        return node.value

    # 二元运算
    if isinstance(node, ast.BinOp):
        op_type = type(node.op)
        func = BIN_OPS.get(op_type)
        if func is None:
            raise CalcError("不支持的运算符: {}".format(op_type.__name__))
        left = _eval_node(node.left, variables)
        right = _eval_node(node.right, variables)
        if isinstance(node.op, ast.Pow) and isinstance(right, (int, float)):
            if abs(right) > MAX_EXPONENT:
                raise CalcError("指数过大（绝对值需 <= {}）".format(MAX_EXPONENT))
        try:
            return func(left, right)
        except ZeroDivisionError:
            raise CalcError("除数不能为 0") from None
        except OverflowError:
            raise CalcError("数值溢出") from None
        except (TypeError, ValueError) as exc:
            raise CalcError("运算失败: {}".format(exc)) from None

    # 一元正负号
    if isinstance(node, ast.UnaryOp):
        func = UNARY_OPS.get(type(node.op))
        if func is None:
            raise CalcError("不支持的一元运算符: {}".format(type(node.op).__name__))
        return func(_eval_node(node.operand, variables))

    # 函数调用
    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name):
            raise CalcError("只支持直接调用内置数学函数")
        name = node.func.id
        func = FUNCTIONS.get(name)
        if func is None:
            raise CalcError("未知函数: {}".format(name))
        if node.keywords:
            raise CalcError("函数不支持关键字参数")
        args = [_eval_node(arg, variables) for arg in node.args]
        try:
            return func(*args)
        except ZeroDivisionError:
            raise CalcError("除数不能为 0") from None
        except OverflowError:
            raise CalcError("数值溢出") from None
        except (ValueError, TypeError) as exc:
            raise CalcError("{}() 参数错误: {}".format(name, exc)) from None

    # 变量 / 常量
    if isinstance(node, ast.Name):
        if node.id in variables:
            return variables[node.id]
        if node.id in CONSTANTS:
            return CONSTANTS[node.id]
        raise CalcError("未知名称: {}".format(node.id))

    raise CalcError("不支持的表达式成分: {}".format(type(node).__name__))


def evaluate(expression: str, variables: Optional[Dict[str, Any]] = None) -> Any:
    """计算表达式字符串，返回结果（int / float）。"""
    variables = {} if variables is None else variables
    expression = expression.strip()
    if not expression:
        raise CalcError("表达式为空")
    # 兼容用 ^ 表示乘方的习惯写法
    expression = expression.replace("^", "**")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        raise CalcError("语法错误: {!r}".format(expression)) from None
    except (ValueError, MemoryError):
        raise CalcError("表达式无法解析") from None
    return _eval_node(tree, variables)


# ---------------------------------------------------------------------------
# 高精度模式（Decimal）
# ---------------------------------------------------------------------------

DECIMAL_BIN_OPS: Dict[type, Callable[[Any, Any], Any]] = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Mod: operator.mod,
}


def _to_decimal(value: Any) -> Decimal:
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, float):
        if math.isinf(value) or math.isnan(value):
            raise CalcError("高精度模式不支持 inf / nan")
        # 经由字符串转换，避免把二进制浮点误差带入
        return Decimal(str(value))
    raise CalcError("高精度模式不支持的值: {!r}".format(value))


def _eval_decimal_node(node: ast.AST, variables: Dict[str, Any]) -> Decimal:
